import gc
import os
import sys
from io import BytesIO

import pytest

import click
from click.exceptions import ClickException
from click.testing import CliRunner
from click.testing import StreamMixer
from click.testing import _NamedTextIOWrapper


def test_runner():
    @click.command()
    def test():
        i = click.get_binary_stream("stdin")
        o = click.get_binary_stream("stdout")
        while True:
            chunk = i.read(4096)
            if not chunk:
                break
            o.write(chunk)
            o.flush()

    runner = CliRunner()
    result = runner.invoke(test, input="Hello World!\n")
    assert not result.exception
    assert result.output == "Hello World!\n"


def test_named_text_io_wrapper_does_not_close_buffer():
    buffer = BytesIO()
    first = _NamedTextIOWrapper(
        buffer, encoding="utf-8", name="<first>", mode="w"
    )
    second = _NamedTextIOWrapper(
        buffer, encoding="utf-8", name="<second>", mode="w"
    )

    first.write("first")
    first.close()
    second.write(" second")
    second.close()

    assert not buffer.closed
    assert buffer.getvalue() == b"first second"


def test_stream_mixer_finalization_does_not_close_streams():
    mixer = StreamMixer()
    stdout = mixer.stdout
    stderr = mixer.stderr
    output = mixer.output
    stdout.write(b"out")
    stderr.write(b"err")

    del mixer
    gc.collect()

    assert stdout.getvalue() == b"out"
    assert stderr.getvalue() == b"err"
    assert output.getvalue() == b"outerr"


